type Req = { url: string; method: string; body?: string };

class ReqBuilder<Set extends string = never> {
  private cfg: Partial<Req> = {};
  url(u: string): ReqBuilder<Set | "url"> { this.cfg.url = u; return this as ReqBuilder<Set | "url">; }
  method(m: string): ReqBuilder<Set | "method"> { this.cfg.method = m; return this as ReqBuilder<Set | "method">; }
  build(this: ReqBuilder<"url" | "method">): Req { return this.cfg as Req; }
}
